INSERT INTO work_order (order_id, material_id, description, order_quantity, start_time, finish_time) VALUES
(#{w.orderId}, #{w.materialId}, #{w.description}, #{w.orderQuantity}, #{w.startTime}, #{w.finishTime})
ON DUPLICATE KEY UPDATE material_id = VALUES(material_id), description = VALUES(description), order_quantity = VALUES(order_quantity), start_time = VALUES(start_time), finish_time = VALUES(finish_time);
